args.CommandLine:
cat << 'EOF' > popup.css
:root {
  color-scheme: dark;
  font-family: "Courier New", ui-monospace, monospace;
  background: #050508;
  color: #0ff;
  --neon-cyan: #0ff;
  --neon-magenta: #f0f;
  --neon-yellow: #ff0;
  --bg-color: #050508;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 360px;
  background: #050508;
  background-image: 
    linear-gradient(rgba(0, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 15px 15px;
  color: var(--neon-cyan);
}

main {
  padding: 20px;
}

.header {
  border-bottom: 2px solid var(--neon-cyan);
  padding-bottom: 12px;
  margin-bottom: 12px;
  box-shadow: 0 4px 5px -2px rgba(0,255,255,0.2);
}

h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--neon-cyan);
  text-shadow: 0 0 5px var(--neon-cyan), 0 0 10px rgba(0,255,255,0.5);
  text-transform: uppercase;
}

.page-status,
.footnote {
  color: #88c;
  font-size: 13px;
  line-height: 1.45;
}

.page-status {
  margin: 0 0 16px;
}

.page-status.error {
  color: var(--neon-magenta);
  text-shadow: 0 0 5px var(--neon-magenta);
}

.page-status.success {
  color: #0f0;
  text-shadow: 0 0 5px #0f0;
}

.job-card {
  padding: 16px 0;
  border-top: 2px solid var(--neon-cyan);
  border-bottom: 2px solid var(--neon-cyan);
  background: rgba(0, 20, 30, 0.4);
}

.job-row,
.counts {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.job-row {
  font-size: 14px;
  font-weight: 700;
  color: #fff;
}

.mode {
  color: var(--neon-yellow);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  text-shadow: 0 0 4px rgba(255, 255, 0, 0.6);
}

.progress-track {
  height: 8px;
  margin: 16px 0;
  overflow: hidden;
  background: #111;
  border: 1px solid var(--neon-cyan);
  box-shadow: inset 0 0 3px #000;
}

.progress-bar {
  width: 0;
  height: 100%;
  background: var(--neon-cyan);
  box-shadow: 0 0 10px var(--neon-cyan);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 4px,
    rgba(0, 0, 0, 0.3) 4px,
    rgba(0, 0, 0, 0.3) 8px
  );
  transition: width 180ms ease;
}

.counts {
  color: #6a9;
  font-size: 12px;
}

.counts strong {
  color: var(--neon-cyan);
  font-size: 14px;
}

.last-error {
  margin: 12px 0 0;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 0, 255, 0.3);
  color: var(--neon-magenta);
  font-size: 12px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.failure-report {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px dashed var(--neon-magenta);
}

.failure-heading {
  margin-bottom: 8px;
  color: var(--neon-magenta);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-shadow: 0 0 3px var(--neon-magenta);
}

.failure-list {
  display: grid;
  gap: 7px;
  max-height: 180px;
  overflow-y: auto;
}

.failure-item {
  padding: 12px 0;
  border-bottom: 1px dashed rgba(255, 0, 255, 0.3);
}

.failure-item:last-child {
  border-bottom: 0;
}

.failure-title {
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.failure-reason {
  margin-top: 4px;
  color: #c7c;
  font-size: 12px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.actions {
  display: grid;
  gap: 8px;
  margin-top: 16px;
}

button {
  min-height: 44px;
  border: 2px solid transparent;
  border-radius: 0;
  font: inherit;
  font-size: 13px;
  font-family: inherit;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  cursor: pointer;
  transition: all 150ms ease;
  position: relative;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}

button:hover:not(:disabled) {
  filter: brightness(1.3);
  text-shadow: 0 0 5px currentColor;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.3;
  filter: grayscale(1);
}

.primary {
  background: var(--neon-magenta);
  color: #000;
}

.primary.upscale {
  background: var(--neon-yellow);
  color: #000;
}

.secondary {
  background: transparent;
  color: var(--neon-cyan);
  border-color: var(--neon-cyan);
}

.secondary:hover:not(:disabled) {
  background: rgba(0, 255, 255, 0.1);
  box-shadow: inset 0 0 10px var(--neon-cyan);
}

.secondary.retry:not(:disabled) {
  border-color: var(--neon-magenta);
  color: var(--neon-magenta);
}
.secondary.retry:hover:not(:disabled) {
  background: rgba(255, 0, 255, 0.1);
  box-shadow: inset 0 0 10px var(--neon-magenta);
}

.danger {
  background: #f00;
  color: #000;
}

.footnote {
  margin: 13px 2px 0;
}

.settings-card {
  background: rgba(0, 20, 30, 0.4);
  border: 1px solid var(--neon-cyan);
  padding: 12px;
  margin: 16px 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-left: 4px solid var(--neon-cyan);
}

.settings-card label {
  color: var(--neon-cyan);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.settings-card input {
  padding: 8px;
  border-radius: 0;
  border: 1px solid rgba(0, 255, 255, 0.3);
  background: rgba(0, 255, 255, 0.05);
  color: #fff;
  font-family: inherit;
}
.settings-card input:focus {
  outline: none;
  border-color: var(--neon-cyan);
  box-shadow: 0 0 5px rgba(0,255,255,0.4);
}

.selection-card {
  background: rgba(0, 20, 30, 0.4);
  border: 1px solid var(--neon-cyan);
  padding: 12px;
  margin-bottom: 16px;
  max-height: 200px;
  overflow-y: auto;
  border-left: 4px solid var(--neon-cyan);
}

.selection-heading {
  margin-bottom: 8px;
  font-weight: 600;
  border-bottom: 1px dashed var(--neon-cyan);
  padding-bottom: 8px;
  color: var(--neon-cyan);
}

.video-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.video-list label {
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #ccc;
  transition: color 0.2s;
}

.video-list label:hover {
  color: var(--neon-cyan);
}

input[type="checkbox"] {
  accent-color: var(--neon-cyan);
}
EOF
